//! Column generation over panel patterns (Gilmore-Gomory) with diving.
//!
//! The master LP chooses how often each pattern (a complete layout of one panel) is cut so that
//! every piece kind is covered at minimum panel area. Its dual values price the piece kinds:
//! pieces that are hard to place get high prices. New patterns are generated by the guillotine
//! packers with these prices as values, so a panel combines "expensive" pieces with suitable
//! fillers. This also works when every size occurs only once (one row per piece).
//!
//! * Root: generate patterns until no improving one is found. The unconstrained guillotine
//!   knapsack bounds every possible pattern, which turns the LP value into a proven lower bound
//!   (Farley bound) even if the generation stops early.
//! * Diving: repeatedly fix the most used pattern, remove its pieces and re-solve the LP for the
//!   rest, generating new patterns for the residual pieces on the way.

use super::knapsack::GridKnapsack;
use super::lp::{solve_cover, LpCol, LpSolution};
use super::model::*;
use super::packer::*;
use super::search::Problem;
use std::collections::{HashMap, HashSet};
use std::time::Instant;

/// Format index, relaxed flag and copies per kind of a pattern.
type PatternKey = (usize, bool, Vec<(usize, u32)>);

/// A pattern for one panel. Real patterns are checked guillotine layouts; relaxed patterns come
/// from the knapsack bound, only serve the lower bound and are never cut.
#[derive(Debug, Clone)]
struct Column {
    spec: usize,
    relaxed: bool,
    /// Copies per kind, sorted by kind.
    counts: Vec<(usize, u32)>,
    /// Placements with the kind of the piece (piece indices are re-assigned on use).
    placed: Vec<(usize, Placed)>,
    cost: f64,
}

pub struct ColumnGeneration<'p, 'a> {
    problem: &'p Problem<'a>,
    /// Piece indices per kind.
    by_kind: Vec<Vec<usize>>,
    columns: Vec<Column>,
    seen: HashMap<PatternKey, usize>,
    /// Single-piece column per kind (always feasible start basis).
    singleton: Vec<usize>,
    grids: Vec<Option<GridKnapsack>>,
}

/// LP over the residual demand: rows are the kinds that still need pieces.
struct ResidualLp {
    solution: LpSolution,
    /// Kind of every row.
    kinds: Vec<usize>,
    /// Column index in the pool of every LP column.
    pool: Vec<usize>,
}

impl<'p, 'a> ColumnGeneration<'p, 'a> {
    pub fn new(problem: &'p Problem<'a>) -> Self {
        let mut by_kind = vec![Vec::new(); problem.kinds];
        for (idx, piece) in problem.pieces.iter().enumerate() {
            by_kind[piece.kind].push(idx);
        }
        let reps: Vec<&Piece> = by_kind.iter().map(|l| &problem.pieces[l[0]]).collect();
        let grids = problem
            .specs
            .iter()
            .map(|spec| GridKnapsack::new(spec, &reps))
            .collect();
        let mut cg = Self {
            problem,
            by_kind,
            columns: Vec::new(),
            seen: HashMap::new(),
            singleton: Vec::new(),
            grids,
        };
        for (kind, rep) in reps.iter().enumerate() {
            let best = problem
                .specs
                .iter()
                .enumerate()
                .filter_map(|(s, spec)| {
                    rep.orientations(false)
                        .find(|o| o.w <= spec.w && o.h <= spec.h)
                        .map(|o| (s, spec, o))
                })
                .min_by(|a, b| {
                    a.1.panel_area
                        .partial_cmp(&b.1.panel_area)
                        .unwrap_or(std::cmp::Ordering::Equal)
                })
                .expect("every piece fits some panel (validated before)");
            let (s, spec, o) = best;
            let placed = Placed {
                piece: cg.by_kind[kind][0],
                x: 0,
                y: 0,
                w: o.w,
                h: o.h,
                rotated: o.rotated,
            };
            let index = cg.columns.len();
            cg.columns.push(Column {
                spec: s,
                relaxed: false,
                counts: vec![(kind, 1)],
                placed: vec![(kind, placed)],
                cost: spec.panel_area,
            });
            cg.seen.insert((s, false, vec![(kind, 1)]), index);
            cg.singleton.push(index);
        }
        cg
    }

    fn spec_of(&self, bin: &PackedBin) -> usize {
        self.problem
            .specs
            .iter()
            .position(|s| s.type_index == bin.spec.type_index)
            .expect("bin uses a known format")
    }

    /// Pattern index of a panel (if it is in the pool).
    fn column_of(&self, bin: &PackedBin) -> Option<usize> {
        let mut counts: Vec<(usize, u32)> = Vec::new();
        let mut kinds: Vec<usize> = bin
            .placed
            .iter()
            .map(|p| self.problem.pieces[p.piece].kind)
            .collect();
        kinds.sort_unstable();
        for kind in kinds {
            match counts.last_mut() {
                Some((k, c)) if *k == kind => *c += 1,
                _ => counts.push((kind, 1)),
            }
        }
        self.seen.get(&(self.spec_of(bin), false, counts)).copied()
    }

    /// Adds the panels of an existing plan as patterns.
    pub fn add_bins(&mut self, bins: &[PackedBin]) {
        for bin in bins {
            let spec = self.spec_of(bin);
            self.add_column(spec, &bin.placed);
        }
    }

    fn add_column(&mut self, spec: usize, placed: &[Placed]) -> bool {
        if placed.is_empty() {
            return false;
        }
        let mut counts: Vec<(usize, u32)> = Vec::new();
        let mut with_kind: Vec<(usize, Placed)> = placed
            .iter()
            .map(|p| (self.problem.pieces[p.piece].kind, *p))
            .collect();
        with_kind.sort_by_key(|(k, _)| *k);
        for (kind, _) in &with_kind {
            match counts.last_mut() {
                Some((k, c)) if k == kind => *c += 1,
                _ => counts.push((*kind, 1)),
            }
        }
        let key = (spec, false, counts.clone());
        if self.seen.contains_key(&key) {
            return false;
        }
        self.seen.insert(key, self.columns.len());
        self.columns.push(Column {
            spec,
            relaxed: false,
            counts,
            placed: with_kind,
            cost: self.problem.specs[spec].panel_area,
        });
        true
    }

    fn add_relaxed(&mut self, spec: usize, counts: &[u32]) -> bool {
        let counts: Vec<(usize, u32)> = counts
            .iter()
            .enumerate()
            .filter(|(_, &c)| c > 0)
            .map(|(k, &c)| (k, c))
            .collect();
        let key = (spec, true, counts.clone());
        if counts.is_empty() || self.seen.contains_key(&key) {
            return false;
        }
        self.seen.insert(key, self.columns.len());
        self.columns.push(Column {
            spec,
            relaxed: true,
            counts,
            placed: Vec::new(),
            cost: self.problem.specs[spec].panel_area,
        });
        true
    }

    /// Solves the master LP for the residual demand. Real patterns are capped to the demand;
    /// relaxed patterns (bound only) are used uncapped and only when `relaxed` is set.
    fn solve_lp(
        &mut self,
        demand: &[u32],
        relaxed: bool,
        banned: &HashSet<usize>,
    ) -> Option<ResidualLp> {
        let kinds: Vec<usize> = (0..demand.len()).filter(|&k| demand[k] > 0).collect();
        let mut row_of = vec![usize::MAX; demand.len()];
        for (row, &k) in kinds.iter().enumerate() {
            row_of[k] = row;
        }
        let mut cols = Vec::new();
        let mut pool = Vec::new();
        let mut start = vec![0; kinds.len()];
        for (index, column) in self.columns.iter().enumerate() {
            if (column.relaxed && !relaxed) || banned.contains(&index) {
                continue;
            }
            let entries: Vec<(usize, f64)> = column
                .counts
                .iter()
                .filter(|(k, _)| row_of[*k] != usize::MAX)
                .map(|&(k, c)| {
                    let c = if column.relaxed { c } else { c.min(demand[k]) };
                    (row_of[k], c as f64)
                })
                .collect();
            if entries.is_empty() {
                continue;
            }
            if !column.relaxed
                && column.counts.len() == 1
                && self.singleton[column.counts[0].0] == index
            {
                start[row_of[column.counts[0].0]] = cols.len();
            }
            cols.push(LpCol {
                entries,
                cost: column.cost,
            });
            pool.push(index);
        }
        let rhs: Vec<f64> = kinds.iter().map(|&k| demand[k] as f64).collect();
        let solution = solve_cover(&rhs, &cols, &start)?;
        Some(ResidualLp {
            solution,
            kinds,
            pool,
        })
    }

    fn duals_by_kind(&self, lp: &ResidualLp) -> Vec<f64> {
        let mut duals = vec![0.0; self.problem.kinds];
        for (row, &k) in lp.kinds.iter().enumerate() {
            duals[k] = lp.solution.duals[row];
        }
        duals
    }

    /// Generates patterns for the residual pieces with the packers, valuing pieces by their
    /// dual prices. Returns the number of new patterns with negative reduced cost.
    fn price(&mut self, duals: &[f64], avail: &Avail, variants: usize) -> usize {
        let pieces = self.problem.pieces;
        let ratio: Vec<f64> = (0..self.problem.kinds)
            .map(|k| duals[k] / pieces[self.by_kind[k][0]].inflated_area() as f64)
            .collect();
        let max_ratio = ratio.iter().copied().fold(0.0, f64::max);
        if max_ratio <= 0.0 {
            return 0;
        }
        let mut added = 0;
        for variant in 0..variants {
            let params = PackParams {
                strip_candidates: if variant == 0 { 8 } else { 4 },
                // Pieces without price are only fillers.
                kind_noise: ratio
                    .iter()
                    .map(|r| (r / max_ratio).max(0.0) + if variant == 0 { 0.02 } else { 0.2 })
                    .collect(),
                lookahead: 1,
            };
            let packer = Packer {
                pieces,
                params: &params,
            };
            for (s, spec) in self.problem.specs.iter().enumerate() {
                for method in METHODS {
                    let mut rest = avail.clone();
                    let placed = packer.pack(spec, method, &mut rest);
                    let value: f64 = placed.iter().map(|p| duals[pieces[p.piece].kind]).sum();
                    if value > spec.panel_area * (1.0 + 1e-6) && self.add_column(s, &placed) {
                        added += 1;
                    }
                }
            }
        }
        added
    }

    /// Exact pricing bound: the largest value any guillotine pattern can reach per panel area.
    /// Also tries to realise the relaxed best patterns as real layouts.
    fn bound_and_realise(&mut self, duals: &[f64], deadline: Instant) -> Option<(f64, usize)> {
        let pieces = self.problem.pieces;
        let mut theta: f64 = 0.0;
        let mut patterns = Vec::new();
        let mut added = 0;
        for (s, spec) in self.problem.specs.iter().enumerate() {
            if Instant::now() >= deadline {
                return None;
            }
            let solution = self.grids[s].as_ref()?.solve(duals);
            theta = theta.max(solution.value / spec.panel_area);
            if solution.value > spec.panel_area * (1.0 + 1e-6) {
                if self.add_relaxed(s, &solution.counts) {
                    added += 1;
                }
                patterns.push((s, solution.counts));
            }
        }
        for (s, counts) in patterns {
            let indices = counts.iter().enumerate().flat_map(|(k, &c)| {
                self.by_kind[k]
                    .iter()
                    .copied()
                    .take((c as usize).min(self.by_kind[k].len()))
            });
            let avail = Avail::new(pieces, self.problem.kinds, indices);
            let params = PackParams {
                strip_candidates: 12,
                kind_noise: vec![1.0; self.problem.kinds],
                lookahead: 1,
            };
            let packer = Packer {
                pieces,
                params: &params,
            };
            let spec = &self.problem.specs[s];
            for method in METHODS {
                let mut rest = avail.clone();
                let placed = packer.pack(spec, method, &mut rest);
                let value: f64 = placed.iter().map(|p| duals[pieces[p.piece].kind]).sum();
                if value > spec.panel_area * (1.0 + 1e-6) && self.add_column(s, &placed) {
                    added += 1;
                }
            }
        }
        Some((theta, added))
    }

    fn demand(&self, avail: &Avail) -> Vec<u32> {
        avail.by_kind.iter().map(|l| l.len() as u32).collect()
    }

    /// Root column generation. Returns a proven lower bound for the total panel area
    /// (0 if none could be proven before the deadline).
    pub fn root(&mut self, deadline: Instant, proven: impl Fn(f64) -> bool) -> f64 {
        let all = Avail::new(
            self.problem.pieces,
            self.problem.kinds,
            0..self.problem.pieces.len(),
        );
        let demand = self.demand(&all);
        let mut bound: f64 = 0.0;
        for round in 0..400 {
            if Instant::now() >= deadline {
                break;
            }
            let Some(lp) = self.solve_lp(&demand, true, &HashSet::new()) else {
                break;
            };
            let duals = self.duals_by_kind(&lp);
            let priced = self.price(&duals, &all, 2);
            // The bound is also refreshed while the heuristic still finds patterns.
            if priced > 0 && round % 4 != 3 {
                continue;
            }
            let Some((theta, added)) = self.bound_and_realise(&duals, deadline) else {
                break;
            };
            let dual_value: f64 = duals.iter().zip(&demand).map(|(p, &d)| p * d as f64).sum();
            bound = bound.max(dual_value / theta.max(1.0));
            if proven(bound) || (priced == 0 && (theta <= 1.0 + 1e-6 || added == 0)) {
                break;
            }
        }
        bound
    }

    /// Re-packs the pieces of `bins` (part of a plan) by diving through the pattern LP.
    /// With `ban` the current patterns of these panels are excluded, which forces a different
    /// combination. `noise` > 0 picks patterns randomly in proportion to their LP value.
    pub fn repack(
        &mut self,
        bins: &[PackedBin],
        ban: bool,
        rng: &mut Rng,
        noise: f64,
        deadline: Instant,
    ) -> Option<Vec<PackedBin>> {
        let banned: HashSet<usize> = if ban {
            bins.iter()
                .filter_map(|b| self.column_of(b))
                .filter(|c| !self.singleton.contains(c))
                .collect()
        } else {
            HashSet::new()
        };
        let indices = bins.iter().flat_map(|b| b.placed.iter().map(|p| p.piece));
        let avail = Avail::new(self.problem.pieces, self.problem.kinds, indices);
        self.dive(avail, &banned, rng, noise, deadline)
    }

    /// Dive over all pieces.
    pub fn dive_all(
        &mut self,
        rng: &mut Rng,
        noise: f64,
        deadline: Instant,
    ) -> Option<Vec<PackedBin>> {
        let pieces = self.problem.pieces;
        let avail = Avail::new(pieces, self.problem.kinds, 0..pieces.len());
        self.dive(avail, &HashSet::new(), rng, noise, deadline)
    }

    /// Fixes patterns one by one following the LP of the residual pieces.
    fn dive(
        &mut self,
        mut avail: Avail,
        banned: &HashSet<usize>,
        rng: &mut Rng,
        noise: f64,
        deadline: Instant,
    ) -> Option<Vec<PackedBin>> {
        let pieces = self.problem.pieces;
        let mut bins: Vec<PackedBin> = Vec::new();
        while !avail.is_empty() {
            if Instant::now() >= deadline {
                return None;
            }
            let demand = self.demand(&avail);
            let lp = self.solve_lp(&demand, false, banned)?;
            let duals = self.duals_by_kind(&lp);
            self.price(&duals, &avail, 1);
            let lp = self.solve_lp(&demand, false, banned)?;
            let x = &lp.solution.x;
            let mut fixed: Vec<usize> = Vec::new();
            if noise > 0.0 {
                // Roulette over the used patterns, favouring large LP values.
                let weights: Vec<(usize, f64)> = x
                    .iter()
                    .enumerate()
                    .filter(|(_, &v)| v > 1e-6)
                    .map(|(j, &v)| (j, v * v * (1.0 + noise * rng.unit())))
                    .collect();
                let total: f64 = weights.iter().map(|w| w.1).sum();
                let mut r = rng.unit() * total;
                let mut pick = weights.last()?.0;
                for &(j, w) in &weights {
                    if r < w {
                        pick = j;
                        break;
                    }
                    r -= w;
                }
                fixed.push(lp.pool[pick]);
            } else {
                for (j, &v) in x.iter().enumerate() {
                    for _ in 0..(v + 1e-6).floor() as usize {
                        fixed.push(lp.pool[j]);
                    }
                }
                if fixed.is_empty() {
                    let pick = x
                        .iter()
                        .enumerate()
                        .max_by(|a, b| a.1.partial_cmp(b.1).unwrap_or(std::cmp::Ordering::Equal))?
                        .0;
                    fixed.push(lp.pool[pick]);
                }
            }
            let before = avail.count;
            for index in fixed {
                let column = &self.columns[index];
                let placed: Vec<Placed> = column
                    .placed
                    .iter()
                    .filter_map(|(kind, p)| avail.take(*kind).map(|piece| Placed { piece, ..*p }))
                    .collect();
                if !placed.is_empty() {
                    bins.push(PackedBin::new(
                        self.problem.specs[column.spec].clone(),
                        placed,
                        pieces,
                    ));
                }
            }
            if avail.count == before {
                return None;
            }
        }
        Some(bins)
    }
}
